"use strict";
const STORAGE_KEYS={items:"dasi-yeogi.found-items.v1",alerts:"dasi-yeogi.search-alerts.v1"};
const CATEGORY_STYLE={"지갑·카드":{symbol:"▣",color:"#eadfca"},전자기기:{symbol:"◫",color:"#dce8ef"},가방:{symbol:"▰",color:"#e7d9d5"},"의류·잡화":{symbol:"✦",color:"#e4e0ef"},열쇠:{symbol:"⌁",color:"#e8e2cf"},기타:{symbol:"●",color:"#dcefe2"}};
const seedItems=[
{id:"seed-1",category:"지갑·카드",title:"검은색 카드지갑",description:"얇은 검은색 가죽 카드지갑입니다. 겉면에 작은 사용 흔적이 있어요.",location:"성수역 2번 출구",foundAt:"2026-10-27T09:20",storage:"성수역 고객안전실",secret:"내부 카드 종류와 각인"},
{id:"seed-2",category:"전자기기",title:"흰색 무선 이어폰 케이스",description:"투명 케이스가 씌워진 흰색 무선 이어폰 충전 케이스입니다.",location:"서울숲 잔디마당",foundAt:"2026-10-26T17:40",storage:"서울숲 방문자센터",secret:"케이스 안쪽의 작은 스티커"},
{id:"seed-3",category:"의류·잡화",title:"회색 토끼 키링",description:"손바닥 크기의 회색 토끼 인형 키링입니다.",location:"건대입구역 환승 통로",foundAt:"2026-10-25T20:10",storage:"건대입구역 역무실",secret:"키링 뒤쪽의 글자"},
{id:"seed-4",category:"가방",title:"아이보리색 에코백",description:"초록색 그림이 인쇄된 아이보리 면 에코백입니다.",location:"뚝섬한강공원 편의점 앞",foundAt:"2026-10-24T15:05",storage:"뚝섬 안내센터",secret:"가방 안쪽 물건"},
{id:"seed-5",category:"열쇠",title:"파란 고리가 달린 열쇠",description:"파란색 원형 고리에 열쇠 두 개가 연결되어 있습니다.",location:"성수동 연무장길",foundAt:"2026-10-23T12:30",storage:"성수2가 파출소",secret:"열쇠의 브랜드와 모양"},
{id:"seed-6",category:"전자기기",title:"검은색 보조배터리",description:"작은 직사각형 보조배터리와 짧은 충전선입니다.",location:"왕십리역 5번 출구",foundAt:"2026-10-22T18:55",storage:"왕십리역 고객안전실",secret:"뒷면에 적힌 문구"}
];
const $=(selector,root=document)=>root.querySelector(selector);
const searchForm=$("#search-form"),resultsGrid=$("#results-grid"),emptyState=$("#empty-state"),resultSummary=$("#result-summary"),reportForm=$("#report-form"),reportStatus=$("#report-status"),detailDialog=$("#detail-dialog"),notificationPanel=$("#notification-panel"),panelBackdrop=$("#panel-backdrop"),notificationTrigger=$("#notification-trigger"),notificationList=$("#notification-list"),notificationEmpty=$("#notification-empty"),notificationCount=$("#notification-count"),toast=$("#toast");
let userItems=readStorage(STORAGE_KEYS.items,[]),alerts=readStorage(STORAGE_KEYS.alerts,[]),lastPanelTrigger=null,toastTimer;
function readStorage(key,fallback){try{const value=JSON.parse(localStorage.getItem(key));return Array.isArray(value)?value:fallback}catch(error){console.warn(`저장 데이터를 읽지 못했습니다: ${key}`,error);return fallback}}
function writeStorage(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch(error){console.warn(`저장하지 못했습니다: ${key}`,error);showToast("브라우저 저장 공간을 사용할 수 없어요.");return false}}
function escapeHTML(value){return String(value).replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;").replaceAll('"',"&quot;").replaceAll("'","&#039;")}
function formatDate(value,includeTime=false){const date=new Date(value);if(Number.isNaN(date.getTime()))return value;return new Intl.DateTimeFormat("ko-KR",{month:"long",day:"numeric",...(includeTime?{hour:"2-digit",minute:"2-digit",hour12:false}:{})}).format(date)}
function getAllItems(){return[...userItems,...seedItems].sort((a,b)=>new Date(b.foundAt)-new Date(a.foundAt))}
function getSearchValues(){const data=new FormData(searchForm);return{keyword:String(data.get("keyword")||"").trim(),category:String(data.get("category")||""),location:String(data.get("location")||"").trim(),date:String(data.get("date")||"")}}
function matchesSearch(item,filters){const keyword=filters.keyword.toLocaleLowerCase("ko"),location=filters.location.toLocaleLowerCase("ko"),searchable=`${item.title} ${item.description} ${item.category}`.toLocaleLowerCase("ko");return(!keyword||searchable.includes(keyword))&&(!filters.category||item.category===filters.category)&&(!location||item.location.toLocaleLowerCase("ko").includes(location))&&(!filters.date||item.foundAt.slice(0,10)===filters.date)}
function cardTemplate(item){const style=CATEGORY_STYLE[item.category]||CATEGORY_STYLE.기타;return `<article class="result-card"><div class="card-visual" style="--card-bg:${style.color}"><span class="card-tag">${escapeHTML(item.category)}</span><span class="card-symbol" aria-hidden="true">${style.symbol}</span></div><div class="card-body"><h3>${escapeHTML(item.title)}</h3><div class="card-meta"><span><span aria-hidden="true">⌖</span>${escapeHTML(item.location)}</span><span><span aria-hidden="true">◷</span>${formatDate(item.foundAt,true)} 습득</span></div><p class="card-description">${escapeHTML(item.description)}</p><button class="card-detail-button" type="button" data-detail-id="${escapeHTML(item.id)}" aria-label="${escapeHTML(item.title)} 상세 보기">자세히 보기 <span aria-hidden="true">→</span></button></div></article>`}
function renderResults(){const filters=getSearchValues(),results=getAllItems().filter(item=>matchesSearch(item,filters));resultSummary.textContent=`조건에 맞는 물건 ${results.length}개`;resultsGrid.innerHTML=results.map(cardTemplate).join("");resultsGrid.hidden=results.length===0;emptyState.hidden=results.length!==0;resultsGrid.querySelectorAll("[data-detail-id]").forEach(button=>button.addEventListener("click",()=>openDetail(button.dataset.detailId)))}
function openDetail(id){const item=getAllItems().find(candidate=>candidate.id===id);if(!item)return;const style=CATEGORY_STYLE[item.category]||CATEGORY_STYLE.기타;$("#detail-content").innerHTML=`<div class="detail-visual" style="--card-bg:${style.color}" aria-hidden="true">${style.symbol}</div><div class="detail-body"><p class="eyebrow">${escapeHTML(item.category)}</p><h2 id="detail-title">${escapeHTML(item.title)}</h2><dl class="detail-list"><div><dt>특징</dt><dd>${escapeHTML(item.description)}</dd></div><div><dt>습득 장소</dt><dd>${escapeHTML(item.location)}</dd></div><div><dt>습득 일시</dt><dd>${formatDate(item.foundAt,true)}</dd></div><div><dt>보관 장소</dt><dd>${escapeHTML(item.storage)}</dd></div></dl><p class="ownership-note"><strong>인계 전 꼭 확인해 주세요.</strong><br>보관 장소에 문의할 때 본인만 아는 고유한 특징을 설명해야 합니다. 비공개 확인 힌트와 개인정보는 화면에 표시되지 않습니다.</p></div>`;detailDialog.showModal()}
function makeAlertLabel(alert){const parts=[alert.keyword,alert.category,alert.location,alert.date].filter(Boolean);return parts.length?parts.join(" · "):"모든 새 습득물"}
function saveCurrentAlert(){const filters=getSearchValues(),duplicate=alerts.some(alert=>["keyword","category","location","date"].every(key=>alert[key]===filters[key]));if(duplicate){showToast("이미 같은 검색 조건을 저장했어요.");return}const nextAlerts=[{id:`alert-${Date.now()}`,...filters,createdAt:new Date().toISOString()},...alerts];if(!writeStorage(STORAGE_KEYS.alerts,nextAlerts))return;alerts=nextAlerts;renderAlerts();showToast("검색 조건을 알림으로 저장했어요.")}
function renderAlerts(){notificationCount.textContent=alerts.length;notificationCount.setAttribute("aria-label",`저장된 알림 ${alerts.length}개`);notificationEmpty.hidden=alerts.length!==0;notificationList.innerHTML=alerts.map(alert=>`<article class="notification-item"><h3>${escapeHTML(makeAlertLabel(alert))}</h3><p>${formatDate(alert.createdAt)} 저장 · 새 습득물이 등록되면 이 조건과 비교해요.</p><button class="delete-alert" type="button" data-alert-id="${escapeHTML(alert.id)}" aria-label="${escapeHTML(makeAlertLabel(alert))} 알림 삭제">알림 삭제</button></article>`).join("");notificationList.querySelectorAll("[data-alert-id]").forEach(button=>button.addEventListener("click",()=>deleteAlert(button.dataset.alertId)))}
function deleteAlert(id){const nextAlerts=alerts.filter(alert=>alert.id!==id);if(!writeStorage(STORAGE_KEYS.alerts,nextAlerts))return;alerts=nextAlerts;renderAlerts();showToast("검색 알림을 삭제했어요.")}
function openNotifications(){lastPanelTrigger=document.activeElement;notificationPanel.hidden=false;panelBackdrop.hidden=false;document.body.style.overflow="hidden";$("#close-notifications").focus()}
function closeNotifications(){notificationPanel.hidden=true;panelBackdrop.hidden=true;document.body.style.overflow="";if(lastPanelTrigger instanceof HTMLElement)lastPanelTrigger.focus()}
function showToast(message){window.clearTimeout(toastTimer);toast.textContent=message;toast.hidden=false;toastTimer=window.setTimeout(()=>{toast.hidden=true},2800)}
function setDefaultFoundTime(){const now=new Date();now.setMinutes(now.getMinutes()-now.getTimezoneOffset());$("#report-date").value=now.toISOString().slice(0,16);$("#report-date").max=now.toISOString().slice(0,16)}
searchForm.addEventListener("input",renderResults);searchForm.addEventListener("change",renderResults);searchForm.addEventListener("reset",()=>window.setTimeout(renderResults));$("#save-alert").addEventListener("click",saveCurrentAlert);$("#empty-save-alert").addEventListener("click",saveCurrentAlert);
reportForm.addEventListener("submit",event=>{event.preventDefault();reportStatus.textContent="";const data=new FormData(reportForm),foundAt=String(data.get("foundAt")||"");if(new Date(foundAt)>new Date()){$("#report-date").setCustomValidity("발견 일시는 미래일 수 없어요.");reportForm.reportValidity();$("#report-date").setCustomValidity("");return}if(!reportForm.checkValidity()){reportForm.reportValidity();return}const newItem={id:`user-${Date.now()}`,category:String(data.get("category")),title:String(data.get("title")).trim(),description:String(data.get("description")).trim(),location:String(data.get("location")).trim(),foundAt,storage:String(data.get("storage")).trim(),secret:String(data.get("secret")).trim()},nextItems=[newItem,...userItems];if(!writeStorage(STORAGE_KEYS.items,nextItems))return;userItems=nextItems;reportForm.reset();setDefaultFoundTime();renderResults();reportStatus.textContent="등록했어요. 입력한 내용은 이 브라우저에 저장되며, 검색 결과에서 바로 확인할 수 있어요.";reportStatus.focus()});
notificationTrigger.addEventListener("click",openNotifications);$("#close-notifications").addEventListener("click",closeNotifications);panelBackdrop.addEventListener("click",closeNotifications);$("#close-detail").addEventListener("click",()=>detailDialog.close());detailDialog.addEventListener("click",event=>{const bounds=detailDialog.getBoundingClientRect(),outside=event.clientX<bounds.left||event.clientX>bounds.right||event.clientY<bounds.top||event.clientY>bounds.bottom;if(outside)detailDialog.close()});document.addEventListener("keydown",event=>{if(event.key==="Escape"&&!notificationPanel.hidden)closeNotifications()});
setDefaultFoundTime();renderResults();renderAlerts();
